local _, Private = ...
local L = Private.L

local _G = _G

-- Chattynator profile
function Private:Setup_Chattynator(installer)
	if not Private.IsAddOnLoaded('Chattynator') then Private:Print('Chattynator ' .. L["is not installed or enabled."]) return end

	-- Disable ElvUI chat
	if Private.ElvUI then
		ElvUI[1].private.chat.enable = false
	end

	-- 1080p
	local scaled = Private.Addon.db.global.scaled

	-- Profile name
	local name = (Private.Addon.db.global.dev and 'Luckyone') or 'Luckyone ' .. Private.Version

	-- Profile string
	local importString = [[CHATTY!1!]]

	-- Profile import
	_G.Chattynator.API.ImportString(importString, name)

	-- The values are always ElvUI chat panel db -2
	local profile = _G.CHATTYNATOR_CONFIG.Profiles[name]
	if scaled and profile then
		profile.windows[1].size = { 442, 208 } -- Width, Height
	end

	Private:Print(L["Chattynator profile has been set."], installer)
end
